import { Component, OnInit } from '@angular/core';
import { TreeserviceService } from './treeservice.service';

@Component({
  selector: 'app-tree',
  templateUrl: './tree.component.html',
  styleUrls: ['./tree.component.css']
})
export class TreeComponent implements OnInit {
  treeData: TreeNode[] = [];

  constructor(private treeserviceService: TreeserviceService) {}

  ngOnInit(): void {
    this.treeserviceService.getTreeData().subscribe(data => {
      this.treeData = data.nodes;
    });
  }

  toggle(node: TreeNode): void {
    node.expanded = !node.expanded;
    this.treeserviceService.updateNode(node).subscribe();
  }

  addNode(): void {
    const newNode: TreeNode = {
      id: Math.random().toString(),
      label: 'New Node'
    };
    this.treeserviceService.addNode(newNode).subscribe(() => {
      this.treeData.push(newNode);
    });
  }

  removeSelectedNodes(): void {
    const selectedNodes = document.querySelectorAll('.selected');
    Array.from(selectedNodes).forEach(node => {
      const idx = this.treeData.findIndex(n => n.id === parseInt(node.getAttribute('data-id')));
      if (idx > -1) {
        this.treeData.splice(idx, 1);
      }
    });
  }
}
```

